solutionCode:
pub enum Fileira {
    Frente(i32),
    Fundo,
}

pub fn lugar_da(poltrona: i32) -> Fileira {
    if poltrona < 10 {
        Fileira::Frente(poltrona)
    } else {
        Fileira::Fundo
    }
}

pub fn caixa_da(texto: String) -> Option<i32> {
    match texto.parse() {
        Ok(n) => Some(n),
        Err(_) => None,
    }
}

pub fn bilhete(texto: String) -> String {
    match caixa_da(texto) {
        Some(poltrona) => match lugar_da(poltrona) {
            Fileira::Frente(n) => format!("frente: poltrona {}", n),
            Fileira::Fundo => String::from("fundo"),
        },
        None => String::from("numero invalido"),
    }
}

testsCode:
use desafio::bilhete;
use desafio::caixa_da;

#[test]
fn testa_o_bilhete_da_poltrona_sete() {
    assert_eq!(bilhete(String::from("7")), "frente: poltrona 7");
}

#[test]
fn testa_o_bilhete_da_poltrona_dezenove() {
    assert_eq!(bilhete(String::from("19")), "fundo");
}

#[test]
fn testa_o_bilhete_do_texto_quebrado() {
    assert_eq!(bilhete(String::from("abc")), "numero invalido");
}

#[test]
fn testa_a_caixa_da_poltrona_quatro() {
    assert_eq!(caixa_da(String::from("4")), Some(4));
}

#[test]
fn testa_a_caixa_do_texto_quebrado() {
    assert_eq!(caixa_da(String::from("x")), None);
}

#[test]
fn testa_a_porta_rapida_do_formulario_valido() {
    assert_eq!(caixa_da(String::from("4")).unwrap(), 4);
}
